package net.minecraft.nbt;import java.util.*;public class CompoundTag{Map<String,Number> v=new HashMap<>();public boolean contains(String k){return v.containsKey(k);}public double getDouble(String k){return v.getOrDefault(k,0).doubleValue();}public long getLong(String k){return v.getOrDefault(k,0).longValue();}public int getInt(String k){return v.getOrDefault(k,0).intValue();}public void putDouble(String k,double x){v.put(k,x);}public void putLong(String k,long x){v.put(k,x);}public void putInt(String k,int x){v.put(k,x);}}
